-- 0001_init.sql
--
-- First versioned migration of the Base Vital backend (feature 004-resumen-cirujano).
-- Applied by the backend migration runner (backend/src/adapters/postgres/migrator.ts), which
-- owns the schema_migrations table, takes an advisory lock and runs this file in one transaction.
-- Do not create schema_migrations here. Do not edit this file once applied; add 0002_*.sql instead.
--
-- Source of truth: specs/004-resumen-cirujano/data-model.md.
-- Enum lists here mirror the Zod contracts in libs/contracts/src/enums.ts (checked by
-- backend/tests/contract/schema-enums.test.ts). Keep them in sync.

CREATE EXTENSION IF NOT EXISTS pgcrypto;  -- gen_random_uuid()

-- Crew -----------------------------------------------------------------------

CREATE TABLE crew_members (
  id                  text PRIMARY KEY CHECK (id ~ '^crew-[a-z0-9]{6}$'),
  mission_start_date  date        NOT NULL,  -- date(completedAt) - (missionDay - 1), set on first check
  created_at          timestamptz NOT NULL DEFAULT now()
);

-- Checks ---------------------------------------------------------------------

CREATE TABLE check_records (
  id               uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  client_check_id  uuid NOT NULL UNIQUE,                          -- idempotency key from the tablet
  crew_id          text NOT NULL REFERENCES crew_members (id),
  kind             text NOT NULL CHECK (kind IN ('daily')),
  mission_day      integer NOT NULL CHECK (mission_day >= 1),
  verdict          text NOT NULL CHECK (verdict IN ('ok', 'attention', 'alert')),
  action_key       text,                                          -- NULL when verdict = 'ok'
  symptoms         text[] NOT NULL DEFAULT '{}' CHECK (symptoms <@ ARRAY['dizziness', 'fainting', 'chest_pain', 'shortness_of_breath', 'none']::text[]),
  simulated        boolean NOT NULL,
  readings         jsonb NOT NULL,                                -- tablet snapshot Record<SensorKey, SensorReading>
  completed_at     timestamptz NOT NULL,                          -- tablet clock (CheckRecord.id)
  received_at      timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT action_matches_verdict CHECK (
    (verdict = 'ok' AND action_key IS NULL) OR
    (verdict IN ('attention', 'alert') AND action_key IS NOT NULL AND action_key <> '')
  )
);
CREATE INDEX check_records_crew_time_idx ON check_records (crew_id, completed_at DESC);

CREATE TABLE observations (
  id               bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  check_id         uuid NOT NULL REFERENCES check_records (id) ON DELETE CASCADE,
  indicator        text NOT NULL CHECK (indicator IN ('sleep_hours', 'mood', 'resting_heart_rate', 'blood_pressure', 'body_temperature', 'oxygen_saturation')),
  value_numeric    numeric(6, 2),                                 -- all indicators except blood pressure
  value_systolic   smallint,                                      -- blood pressure only
  value_diastolic  smallint,                                      -- blood pressure only
  unit             text NOT NULL,                                 -- fixed by indicator: h, 1-5, lpm, mmHg, °C, %
  source           text NOT NULL CHECK (source IN ('voice', 'device')),
  confirmed        boolean NOT NULL,
  simulated        boolean NOT NULL,
  captured_at      timestamptz NOT NULL,                          -- Observation.at
  CONSTRAINT value_shape CHECK (
    (indicator = 'blood_pressure'
       AND value_systolic IS NOT NULL AND value_diastolic IS NOT NULL AND value_numeric IS NULL)
    OR
    (indicator <> 'blood_pressure'
       AND value_numeric IS NOT NULL AND value_systolic IS NULL AND value_diastolic IS NULL)
  ),
  CONSTRAINT voice_is_confirmed CHECK (source <> 'voice' OR confirmed),  -- constitution IX
  CONSTRAINT one_value_per_indicator UNIQUE (check_id, indicator)
);

-- Alerts ---------------------------------------------------------------------

CREATE TABLE alerts (
  id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  crew_id     text NOT NULL REFERENCES crew_members (id),
  check_id   uuid NOT NULL UNIQUE REFERENCES check_records (id) ON DELETE CASCADE,  -- at most one alert per check
  urgency     text NOT NULL CHECK (urgency IN ('soon', 'now')),  -- attention -> soon, alert -> now
  status      text NOT NULL DEFAULT 'open' CHECK (status IN ('open', 'decided')),
  decision    text CHECK (decision IN ('manage_on_base', 'consult_surgeon', 'prepare_return')),
  decided_at  timestamptz,
  created_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT decision_matches_status CHECK (
    (status = 'open' AND decision IS NULL AND decided_at IS NULL) OR
    (status = 'decided' AND decision IS NOT NULL AND decided_at IS NOT NULL)
  )
);
CREATE INDEX alerts_queue_idx ON alerts (urgency, created_at) WHERE status = 'open';
